old:
    MissingComponent {
        /// Authoring identity that resolved.
        authoring: String,
        /// Component the track requires.
        component: &'static str,
    },
}

new:
    MissingComponent {
        /// Authoring identity that resolved.
        authoring: String,
        /// Component the track requires.
        component: &'static str,
    },
    /// The target Animation Controller is not using the Animation Set bound by the track.
    AnimationSetMismatch {
        /// Authoring identity that resolved.
        authoring: String,
        /// Animation Set required by the Timeline track.
        expected: AssetId,
        /// Animation Set currently resolved by the target controller, when known.
        actual: Option<AssetId>,
    },
    /// The target Animation Set did not resolve the requested stable motion slot.
    UnresolvedMotionSlot {
        /// Authoring identity that resolved.
        authoring: String,
        /// Animation Set selected by the Timeline track.
        animation_set: AssetId,
        /// Stable motion slot the clip requested.
        motion_slot: MotionSlotId,
    },
    /// Another runtime owner already controls the target Animator.
    AnimationOverrideConflict {
        /// Authoring identity whose Animator could not be acquired.
        authoring: String,
    },
}
